// Fork of "3D grid 2" https://shadertoy.com/view/NtySRV
// variant of https://www.shadertoy.com/view/flGSRV

#define rot(a)    mat2(cos(a+vec4(0,11,33,0)))        // rotation
#define H(p)      fract(sin(dot(p, R-13.7)) * 4e5 )   // hash

void mainImage(out vec4 O, vec2 U)
{
    float t=9.; 

    vec3  R = iResolution, Y = vec3(0,1,0),
          D = normalize(vec3((U+U-R.xy)/R.y, -3.)),   // ray direction
          p = vec3(0,0,25), q,a,i,d,                  // marching point along ray 
          M = iMouse.z > 0. ? iMouse.xyz/R -.5: vec3(10,12,0)/1e2*cos(iTime+vec3(0,11,0))+vec3(0,.12,0); 

    for ( O=vec4(1); O.x > 0. && t > .005; O-=.01 ) {
        q = p,
        q.yz *= rot(.5-6.3*M.y),                      // rotations
        q.xz *= rot(-6.3*M.x),
        a = abs(q), i = floor(q),
        q = fract(q)-.5;                              // cells
         t = min(t, abs(q[int(3.*H(i))])-.01 ),       // random wall
         t = max( t, max(a.x, max(a.y,a.z))-6. ),     // clamp to cube

        p += .4*t*D;                                  // step forward = dist to obj
    }
}
